ytes\\": 3884,\\n      \\"sha256\\": \\"7725f2f662f8e720426ad57f74305184e932497b7e33cee2a24f9dd3344278dc\\"\\n    },\\n    \\"actual/berberis/kernel_api/proc_maps_kernel_statfs.h\\": {\\n      \\"bytes\\": 2480,\\n      \\"sha256\\": \\"77f72e71bb8e5f9239287cfb4899fc4d83c38b61f3cd78cd93909da792d751a0\\"\\n    },\\n    \\"actual/berberis/kernel_api/proc_maps_path.h\\": {\\n      \\"bytes\\": 1314,\\n      \\"sha256\\": \\"0993c19732160affe859ddf323f81206917296ce81524ebeab1609d6ab13ee4c\\"\\n    },\\n    \\"actual/berberis/kernel_api/proc_maps_provenance.h\\": {\\n      \\"bytes\\": 4330,\\n      \\"sha256\\": \\"e21bc5dbe7b92893f52cd9a9d7d3ffe30cd813485aa4d2ebdadb435350e0fa68\\"\\n    },\\n    \\"actual/berberis/kernel_api/proc_maps_raw_metadata_owner.h\\": {\\n      \\"bytes\\": 2750,\\n      \\"sha256\\": \\"b3c0fed34550a113c993808f31ee6eb3708b58b856530c0acf8cc7bfe22306cc\\"\\n    },\\n    \\"actual/proc_maps_factory_wire.cc\\": {\\n      \\"bytes\\": 8661,\\n      \\"sha256\\": \\"4a39b504188c5eaf56320f4e10d48285ea8954d816a98a2d5b7b684d38c48608\\"\\n    },\\n    \\"actual/proc_maps_fd_owner.cc\\": {\\n      \\"bytes\\": 20933,\\n      \\"sha256\\": \\"b9ab891c0a09a04661bf4c9306978502094b08606c33d8ea2742f5eba3d29c5e\\"\\n    },\\n    \\"actual/proc_maps_path.cc\\": {\\n      \\"bytes\\": 7026,\\n      \\"sha256\\": \\"48b0c85bdd0fb1b08b7e9478d7642ffe199d321c6bf80304eaba9c42f62b9765\\"\\n    },\\n    \\"actual/proc_maps_provenance.cc\\": {\\n      \\"bytes\\": 32621,\\n      \\"sha256\\": \\"f4e6685f5b689d3b408dc6aa7723e36b2174e6e2545e743fbb5c5896f6142137\\"\\n    },\\n    \\"actual/proc_maps_raw_metadata_owner.cc\\": {\\n      \\"bytes\\": 25425,\\n      \\"sha256\\": \\"4400b1db44f3d7c46dd25136dba8599bc934f2ef28963c289cde1953960536a6\\"\\n    },\\n    \\"audit_two_workers.py\\": {\\n      \\"bytes\\": 6141,\\n      \\"sha256\\": \\"aed6a7b8b352c5cafa6ea16529338a0d7a4908868a28b3a68b7a6be1d21cf26b\\"\\n    },\\n    \\"audit_worker_binary.py\\": {\\n      \\"bytes\\": 5841,\\n      \\"sha256\\": \\"bda5819b28745571a9a236199052e047b806a96a7d094e0f61732d3858e71bc9\\"\\n    },\\n    \\"owned_nofile_controls.cc\\": {\\n      \\"bytes\\": 39131,\\n      \\"sha256\\": \\"62c53acf7a58054a3ff4ea83e051a5630405955fe79cc59dcccc99b37e4264ef\\"\\n    },\\n    \\"owner_probe.cpp\\": {\\n      \\"bytes\\": 3183,\\n      \\"sha256\\": \\"d508c044c64479f07d07ff689e4cb1bce9a02249da08237bed6c8f323cb035bf\\"\\n    },\\n    \\"preimage/berberis/kernel_api/proc_maps_raw_metadata_owner.h\\": {\\n      \\"bytes\\": 150,\\n      \\"sha256\\": \\"790cb30a463ae05385add83bbbc73c0b6a083cc18471e2894d53a87b4d9f113b\\"\\n    },\\n    \\"preimage/proc_maps_raw_metadata_owner.cc\\": {\\n      \\"bytes\\": 22735,\\n      \\"sha256\\": \\"489264a8fcb8e0607a671b78363970caf17f0bb4589b46c12e77329daf17b818\\"\\n    },\\n    \\"r21_cases_reused.cc\\": {\\n      \\"bytes\\": 25727,\\n      \\"sha256\\": \\"04700afc17b6d94f15f9d6bef0ca3c958988804ec82eca137f06348f7bf46155\\"\\n    },\\n    \\"src/local/pocket4/fdownerprobe/ProbeInstrumentation.java\\": {\\n      \\"bytes\\": 1875,\\n      \\"sha256\\": \\"0878b6fe3d0059432b1bf7fc8041838ea9b36c3d1d0cfd9384b05d64bf52719f\\"\\n    }\\n  }\\n}\\n", "control-source/build-r3.py": "#!/usr/bin/env python3\\n\\"\\"\\"Build a headless owned APK using existing pinned Pocket4 tools; never install.\\"\\"\\"\\nfrom pathlib import Path, PurePosixPath\\nimport ast\\nimport datetime\\nimport hashlib\\nimport json\\nimport os\\nimport re\\nimport resource\\nimport struct\\nimport subprocess\\nimport sys\\nimport zipfile\\n\\nWORK = Path(\'/home/alex/Documents/Codex/2026-10-23/new-chat-2/work\')\\nDEFINITIONS = WORK / \'native-jni-oracle-v6/build.py\'\\nDEFINITIONS_SHA = \'0e77ac152e7fd91cb6e5171e189394fbdd4c30f6e62af919c7ca31dcab5ceb59\'\\nNDK_ARCHIVE = Path(\'/home/alex/.local/state/pocket4-app-production-20261028-session/ndk-toolchain/android-ndk-r27d-linux.zip\')\\nNDK_PREFIX = \'android-ndk-r27d/toolchains/llvm/prebuilt/linux-x86_64/sysroot/\'\\n\\n\\ndef sha(path):\\n    with Path(path).open(\'rb\') as stream:\\n        return hashlib.file_digest(stream, \'sha256\').hexdigest()\\n\\n\\ndef main():\\n    root = Path(sys.argv[1]).resolve()\\n    kind = sys.argv[2]\\n    attempt = int(sys.argv[3])\\n    assert kind in (\'owner\', \'signal\', \'signal-r3\') and 1 <= attempt <= 9\\n    os.umask(0o077)\\n    resource.setrlimit(resource.RLIMIT_CORE, (0, 0))\\n    allowed = os.sched_getaffinity(0)\\n    os.sched_setaffinity(0, {6 if 6 in allowed else min(allowed)})\\n    build = root / (\'build-attempt-\' + str(attempt))\\n    build.mkdir(mode=0o700)\\n    report = {\'state\': \'BUILDING\', \'kind\': kind, \'commands\': [],\\n              \'actual_android_executed\': False,\\n              \'started_utc\': datetime.datetime.now(datetime.timezone.utc).isoformat()}\\n\\n    def save():\\n        (build / \'build-result.json\').write_text(json.dumps(report, indent=2) + \'\\\\n\')\\n\\n    try:\\n        assert sha(DEFINITIONS) == DEFINITIONS_SHA\\n        scope = {\'__name__\': \'pinned_v6_definitions\', \'__file__\': str(DEFINITIONS)}\\n        exec(compile(DEFINITIONS.read_bytes(), str(DEFINITIONS), \'exec\'), scope)\\n        pins = scope[\'TOOL_PINS\']\\n        assert all(sha(path) == expected for path, expected in pins.items())\\n        assert sha(scope[\'TEST_KEY\']) == scope[\'TEST_KEY_SHA\']\\n        # Reuse only the existing, hash-pinned owned-test signing configuration.\\n        # Do not put signing arguments or credentials in the build receipt.\\n        definitions_ast = ast.parse(DEFINITIONS.read_text())\\n        signing_literals = {n.value for n in ast.walk(definitions_ast)\\n                            if isinstance(n, ast.Constant) and isinstance(n.value, str)\\n                            and n.value.startswith(\'pass:\')}\\n        assert len(signing_literals) == 1, \'ambiguous pinned test signing argument\'\\n        signing_argument = next(iter(signing_literals))\\n        signing_aliases = set()\\n        for node in ast.walk(definitions_ast):\\n            if isinstance(node, ast.List):\\n                for index, item in enumerate(node.elts[:-1]):\\n                    if isinstance(item, ast.Constant) and item.value == \'--ks-key-alias\':\\n                        alias = node.elts[index + 1]\\n                        assert isinstance(alias, ast.Constant) and isinstance(alias.value, str)\\n                        signing_aliases.add(alias.value)\\n        assert len(signing_aliases) <= 1, \'ambiguous pinned test signing alias\'\\n        signing_alias_arguments = [\'--ks-key-alias\', next(iter(signing_aliases))] if signing_aliases else []\\n        archive_sha = sha(NDK_ARCHIVE)\\n        report[\'ndk_archive\'] = {\'sha256\': archive_sha, \'bytes\': NDK_ARCHIVE.stat().st_size,\\n                                 \'provenance\': \'existing retained NDK archive; hash observed before extraction\'}\\n        sysroot = build / \'sysroot\'\\n        sysroot.mkdir()\\n        extracted = {}\\n        with zipfile.ZipFile(NDK_ARCHIVE) as archive:\\n            for member in archive.infolist():\\n                if not member.filename.startswith(NDK_PREFIX) or member.is_dir():\\n                    continue\\n                relative = member.filename[len(NDK_PREFIX):]\\n                selected = relative.startswith(\'usr/include/\') or relative in (\\n                    \'usr/lib/x86_64-linux-android/24/libc.so\',\\n                    \'usr/lib/aarch64-linux-android/24/libc.so\')\\n                if not selected:\\n                    continue\\n                part = PurePosixPath(relative)\\n                assert not part.is_absolute() and \'..\' not in part.parts\\n                assert (member.external_attr >> 16) & 0o170000 != 0o120000\\n                target = sysroot / relative\\n                target.parent.mkdir(exist_ok=True, parents=True)\\n                data = archive.read(member)\\n                target.write_bytes(data)\\n                extracted[relative] = hashlib.sha256(data).hexdigest()\\n        (build / \'ndk-extracted-sha256.json\').write_text(json.dumps(extracted, indent=2) + \'\\\\n\')\\n        source_files = sorted(p for p in root.rglob(\'*\') if p.is_file()\\n                              and not any(x.startswith(\'build-attempt-\') for x in p.relative_to(root).parts))\\n        source_pins = {str(p.relative_to(root)): sha(p) for p in source_files}\\n        clang, jdk, sdk, r8, aapt, align, signer = [scope[k] for k in (\\n            \'CLANG_DIR\', \'JDK\', \'SDK\', \'R8\', \'AAPT\', \'ALIGN\', \'SIGNER\')]\\n        abi, triple, library = (\'x86_64\', \'x86_64-linux-android\', \'fdownerprobe\') if kind == \'owner\' else (\\n            \'arm64-v8a\', \'aarch64-linux-android\', \'owned_signal_probe\')\\n        package = \'local.pocket4.fdownerprobe.r11\' if kind == \'owner\' else (\'org.droidloom.signalprobe.r3\' if kind == \'signal-r3\' else \'org.droidloom.signalprobe\')\\n        for directory in (\'classes\', \'dex\', \'res\', \'lib/\' + abi):\\n            (build / directory).mkdir(parents=True, mode=0o700)\\n        env = {\'PATH\': str(jdk) + \':/usr/bin:/bin\', \'LANG\': \'C\', \'LC_ALL\': \'C\', \'TMPDIR\': str(build)}\\n\\n        def run(name, args, timeout=100, secret=False):\\n            argv = list(map(str, args))\\n            proc = subprocess.run(argv, cwd=build, env=env, capture_output=True, timeout=timeout)\\n            stdout = proc.stdout.replace(signing_argument.encode(), b\'[test-signing]\')\\n            stderr = proc.stderr.replace(signing_argument.encode(), b\'[test-signing]\')\\n            (build / (name + \'.stdout\')).write_bytes(stdout)\\n            (build / (name + \'.stderr\')).write_bytes(stderr)\\n            report[\'commands\'].append({\'name\': name, \'argv\': [\'[existing owned-test signing configuration]\'] if secret else argv,\\n                \'returncode\': proc.returncode, \'stdout_sha256\': sha(build / (name + \'.stdout\')),\\n                \'stderr_sha256\': sha(build / (name + \'.stderr\'))})\\n            save()\\n            assert proc.returncode == 0, (name, proc.returncode, stderr.decode(errors=\'replace\')[-5000:])\\n            return stdout.decode(errors=\'replace\')\\n\\n        lib = build / \'lib\' / abi / (\'lib\' + library + \'.so\')\\n        sources = [root / \'owner_probe.cpp\'] if kind == \'owner\' else sorted((root / \'native\').glob(\'*.c\')) + sorted((root / \'native\').glob(\'*.S\'))\\n        assert sources and all(p.is_file() for p in sources)\\n        common = [clang / (\'clang++\' if kind == \'owner\' else \'clang\'), \'-target\', triple + \'24\',\\n            \'--sysroot=\' + str(sysroot), \'-shared\', \'-nostdlib\', \'-fPIC\', \'-fuse-ld=lld\',\\n            \'-Wl,--build-id=sha1,--no-undefined,--allow-shlib-undefined,--no-as-needed,--soname,lib\' + library + \'.so,-z,noexecstack,-z,relro,-z,now\',\\n            \'-fno-stack-protector\', \'-fvisibility=hidden\', \'-Wall\', \'-Wextra\', \'-Werror\', \'-O1\',\\n            \'-I\', jdk.parent / \'include\', \'-I\', jdk.parent / \'include/linux\',\\n            \'-I\', sysroot / \'usr/include\' / triple]\\n        if kind == \'owner\':\\n            common += [\'-std=c++17\', \'-fno-exceptions\', \'-fno-rtti\', \'-nostdinc++\', \'-isystem\', sysroot / \'usr/include/c++/v1\']\\n        else:\\n            common += [\'-std=c11\', \'-D_GNU_SOURCE\', \'-march=armv8-a\', \'-mno-outline-atomics\', \'-mbranch-protection=none\', \'-fno-omit-frame-pointer\']\\n        run(\'compile-native\', common + sources + [sysroot / (\'usr/lib/\' + triple + \'/24/libc.so\'), \'-o\', lib])\\n        java = sorted((root / (\'src\' if kind == \'owner\' else \'java\')).rglob(\'*.java\'))\\n        run(\'javac\', [jdk / \'javac\', \'-J-XX:ActiveProcessorCount=1\', \'-J-XX:+UseSerialGC\', \'-J-Xmx256m\',\\n            \'-source\', \'8\', \'-target\', \'8\', \'-bootclasspath\', sdk, \'-d\', build / \'classes\'] + java)\\n        run(\'d8\', [jdk / \'java\', \'-XX:ActiveProcessorCount=1\', \'-XX:+UseSerialGC\', \'-Xmx256m\', \'-cp\', r8,\\n            \'com.android.tools.r8.D8\', \'--lib\', sdk, \'--min-api\', \'24\', \'--output\', build / \'dex\'] + sorted((build / \'classes\').rglob(\'*.class\')))\\n        run(\'aapt-package\', [aapt, \'package\', \'-f\', \'-M\', root / \'AndroidManifest.xml\', \'-S\', build / \'res\', \'-I\', sdk, \'-F\', build / \'unsigned.apk\'])\\n        with zipfile.ZipFile(build / \'unsigned.apk\', \'a\', compression=zipfile.ZIP_STORED) as archive:\\n            archive.write(build / \'dex/classes.dex\', \'classes.dex\')\\n            archive.write(lib, \'lib/\' + abi + \'/\' + lib.name)\\n        run(\'align\', [align, \'-f\', \'4\', build / \'unsigned.apk\', build / \'aligned.apk\'])\\n        apk = build / (library + \'.apk\')\\n        run(\'sign\', [signer, \'sign\', \'--ks\', scope[\'TEST_KEY\']] + signing_alias_arguments + [\\n            \'--ks-pass\', signing_argument, \'--key-pass\', signing_argument, \'--out\', apk, build / \'aligned.apk\'], secret=True)\\n        signature = run(\'signature\', [signer, \'verify\', \'--verbose\', \'--print-certs\', apk])\\n        run(\'alignment\', [align, \'-c\', \'4\', apk])\\n        badging = run(\'badging\', [aapt, \'dump\', \'badging\', apk])\\n        permissions = run(\'permissions\', [aapt, \'dump\', \'permissions\', apk])\\n        manifest = run(\'manifest\', [aapt, \'dump\', \'xmltree\', apk, \'AndroidManifest.xml\'])\\n        elf = run(\'ELF\', [\'/usr/bin/readelf\', \'-h\', \'-d\', \'--dyn-syms\', \'-l\', \'-r\', \'-V\', \'--wide\', lib])\\n        run(\'disassembly\', [clang / \'llvm-objdump\', \'-d\', lib])\\n        assert \'uses-permission:\' not in permissions and \'launchable-activity:\' not in badging\\n        assert \\"package: name=\'\\" + package + \\"\'\\" in badging\\n        assert \\"native-code: \'\\" + abi + \\"\'\\" in badging\\n        assert \'Signer #1 certificate SHA-256 digest: \' + scope[\'SIGNER_CERT_SHA\'] in signature\\n        assert \'Verified using v2 scheme (APK Signature Scheme v2): true\' in signature\\n        assert \'Verified using v3 scheme (APK Signature Scheme v3): true\' in signature\\n        data = lib.read_bytes()\\n        assert data[:6] == b\'\\\\x7fELF\\\\x02\\\\x01\' and struct.unpack_from(\'<H\', data, 16)[0] == 3\\n        assert struct.unpack_from(\'<H\', data, 18)[0] == (62 if kind == \'owner\' else 183)\\n        needed = re.findall(r\'\\\\(NEEDED\\\\).*Shared library: \\\\[(.*?)\\\\]\', elf)\\n        assert needed == [\'libc.so\'] and \'BIND_NOW\' in elf\\n        po = struct.unpack_from(\'<Q\', data, 32)[0]\\n        ps, pc = struct.unpack_from(\'<HH\', data, 54)\\n        ph = [struct.unpack_from(\'<IIQQQQQQ\', data, po + i * ps) for i in range(pc)]\\n        assert not any(p[0] == 1 and p[1] & 3 == 3 for p in ph)\\n        assert any(p[0] == 0x6474e551 and p[1] == 6 for p in ph) and any(p[0] == 0x6474e552 for p in ph)\\n        with zipfile.ZipFile(apk) as archive:\\n            assert [n for n in archive.namelist() if n.startswith(\'lib/\')] == [\'lib/\' + abi + \'/\' + lib.name]\\n            assert archive.read(\'lib/\' + abi + \'/\' + lib.name) == data\\n        assert all(sha(root / name) == expected for name, expected in source_pins.items())\\n        assert all(sha(path) == expected for path, expected in pins.items())\\n        assert sha(NDK_ARCHIVE) == archive_sha\\n        report.update(state=\'BUILT_STATIC_VERIFIED_ANDROID_UNRUN\', package=package, ABI=abi,\\n            APK={\'path\': str(apk), \'sha256\': sha(apk), \'bytes\': apk.stat().st_size},\\n            ELF={\'sha256\': sha(lib), \'needed\': needed, \'NX_RELRO_NOW_no_WX\': True},\\n            source_sha256=source_pins, builder_sha256=sha(__file__),\\n            tools_sha256={str(p): h for p, h in pins.items()}, no_permissions=True, no_activity=True)\\n    except Exception as error:\\n        report.update(state=\'FAILED\', error=repr(error))\\n    report[\'finished_utc\'] = datetime.datetime.now(datetime.timezone.utc).isoformat()\\n    save()\\n    print(json.dumps({\'state\': report[\'state\'], \'error\': report.get(\'error\'), \'APK\': report.get(\'APK\')}), flush=True)\\n    return 0 if report[\'state\'] == \'BUILT_STATIC_VERIFIED_ANDROID_UNRUN\' else 1\\n\\n\\nif __name__ == \'__main__\':\\n    raise SystemExit(main())\\n", "control-source/build_android.py": "#!/usr/bin/env python3\\nimport ctypes,datetime,hashlib,json,os,re,signal,stat,subprocess,sys,time,shlex\\nfrom pathlib import Path\\n\\ndef require(ok, message):\\n    if not ok:\\n        raise RuntimeError(message)\\n\\ndef utc():\\n    return datetime.datetime.now(datetime.timezone.utc).isoformat()\\n\\ndef sha(data):\\n    return hashlib.sha256(data).hexdigest()\\n\\ndef identity(st):\\n    return [st.st_dev, st.st_ino, st.st_mode, st.st_size, st.st_mtime_ns, st.st_ctime_ns]\\n\\ndef held(path, maximum=4*1024*1024):\\n    fd = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW)\\n    try:\\n        before = os.fstat(fd)\\n        require(stat.S_ISREG(before.st_mode) and before.st_size <= maximum, \'unexpected file type/size: \'+str(path))\\n        parts = []\\n        total = 0\\n        while total <= maximum:\\n            chunk = os.read(fd, min(65536, maximum+1-total))\\n            if not chunk:\\n                break\\n            parts.append(chunk)\\n            total += len(chunk)\\n        data = b\'\'.join(parts)\\n        require(total == before.st_size and identity(before) == identity(os.fstat(fd)) == identity(path.lstat()), \'source changed during read: \'+str(path))\\n        return data, {\'path\': str(path), \'bytes\': total, \'sha256\': sha(data), \'identity\': identity(before)}\\n    finally:\\n        os.close(fd)\\n\\ndef write_new(path, data):\\n    path.parent.mkdir(parents=True, exist_ok=True)\\n    if not isinstance(data, bytes):\\n        data = (json.dumps(data, indent=2, sort_keys=True)+\'\\\\n\').encode()\\n    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)\\n    with os.fdopen(fd, \'wb\') as stream:\\n        stream.write(data)\\n        stream.flush()\\n        os.fsync(stream.fileno())\\n    return {\'path\': str(path), \'bytes\': len(data), \'sha256\': sha(data)}\\n\\ndef real_directory(path):\\n    for item in (path, *path.parents):\\n        require(stat.S_ISDIR(item.lstat().st_mode), \'directory alias rejected: \'+str(item))\\n\\ndef children():\\n    return [int(x) for x in Path(\'/proc/self/task/%d/children\' % os.getpid()).read_text().split()]\\n\\ndef cleanup_children():\\n    initial = children()\\n    errors = []\\n    reaped = []\\n    deadline = time.monotonic()+8\\n    while children() and time.monotonic() < deadline:\\n        for pid in children():\\n            try:\\n                got, status = os.waitpid(pid, os.WNOHANG)\\n                if got:\\n                    reaped.append({\'pid\': got, \'status\': status})\\n                    continue\\n                fd = os.pidfd_open(pid, 0)\\n                try:\\n                    signal.pidfd_send_signal(fd, signal.SIGKILL)\\n                finally:\\n                    os.close(fd)\\n            except ChildProcessError:\\n                continue\\n            except ProcessLookupError:\\n                continue\\n            except Exception as error:\\n                errors.append(repr(error))\\n        time.sleep(0.02)\\n    remaining = children()\\n    return {\'initial_owned_children\': initial, \'forced_cleanup\': bool(initial), \'reaped\': reaped, \'remaining\': remaining, \'errors\': errors}\\n\\ndef command(argv, cwd, env, label, records, maximum_seconds=180):\\n    require(not children(), \'unreaped child before command\')\\n    maximum_seconds = min(maximum_seconds, DEADLINE-time.monotonic())\\n    require(maximum_seconds > 0, \'owned overall deadline exhausted\')\\n    stdout = OUT/(label+\'.stdout\')\\n    stderr = OUT/(label+\'.stderr\')\\n    started = utc()\\n    with stdout.open(\'xb\') as out, stderr.open(\'xb\') as err:\\n        proc = subprocess.Popen(argv, cwd=cwd, env=env, stdin=subprocess.DEVNULL,\\n                                stdout=out, stderr=err, start_new_session=True)\\n        timeout = False\\n        try:\\n            code = proc.wait(timeout=maximum_seconds)\\n        except subprocess.TimeoutExpired:\\n            timeout = True\\n            os.killpg(proc.pid, signal.SIGTERM)\\n            try:\\n                code = proc.wait(timeout=3)\\n            except subprocess.TimeoutExpired:\\n                os.killpg(proc.pid, signal.SIGKILL)\\n                code = proc.wait(timeout=3)\\n    output, outrow = held(stdout, 32*1024*1024)\\n    _, errrow = held(stderr, 4*1024*1024)\\n    row = {\'argv\': [str(x) for x in argv], \'cwd\': str(cwd), \'label\': label,\\n           \'started_utc\': started, \'finished_utc\': utc(), \'returncode\': code,\\n           \'timed_out\': timeout, \'stdout\': outrow, \'stderr\': errrow}\\n    records.append(row)\\n    require(code == 0 and not timeout, \'command failed: \'+label)\\n    require(not children(), \'command left owned children: \'+label)\\n    return output\\n\\ndef resource_text(directory_fd, name):\\n    fd = os.open(name, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW, dir_fd=directory_fd)\\n    try:\\n        raw = os.read(fd, 32769)\\n        require(len(raw) <= 32768, \'owned resource observation exceeds bound\')\\n        return raw.decode(\'ascii\').strip()\\n    finally:\\n        os.close(fd)\\n\\ndef resource_events(text):\\n    rows = [line.split() for line in text.splitlines()]\\n    require(rows and all(len(row) == 2 and row[1].isdigit() for row in rows), \'malformed owned memory.events\')\\n    events = {row[0]:int(row[1]) for row in rows}\\n    require(len(events) == len(rows) and all(k in events for k in [\'oom\',\'oom_kill\',\'oom_group_kill\']), \'incomplete or duplicate owned memory.events\')\\n    return events\\n\\ndef resource_snapshot(directory_fd, membership):\\n    observed = Path(\'/proc/self/cgroup\').read_text().strip()\\n    require(observed == membership, \'controller cgroup membership changed\')\\n    path = Path(\'/sys/fs/cgroup\')/membership[3:].lstrip(\'/\')\\n    held_st = os.fstat(directory_fd)\\n    named_st = path.lstat()\\n    require(stat.S_ISDIR(held_st.st_mode) and stat.S_ISDIR(named_st.st_mode) and\\n            (held_st.st_dev,held_st.st_ino) == (named_st.st_dev,named_st.st_ino), \'owned invocation cgroup identity changed\')\\n    fields = {name:resource_text(directory_fd,name) for name in [\\n        \'cgroup.procs\',\'memory.events\',\'memory.current\',\'memory.peak\',\'memory.high\',\'memory.max\',\\n        \'memory.swap.current\',\'memory.swap.peak\',\'memory.swap.max\',\'cpu.max\']}\\n    require(str(os.getpid()) in fields[\'cgroup.procs\'].split(), \'controller is not in the held invocation\')\\n    require(fields[\'memory.max\'] == \'1073741824\' and fields[\'cpu.max\'] == \'100000 100000\', \'owned resource limits do not match the request\')\\n    for key in [\'memory.current\',\'memory.peak\',\'memory.swap.current\',\'memory.swap.peak\']:\\n        require(fields[key].isdigit(), \'invalid owned resource counter: \'+key)\\n    return {\'observed_utc\':utc(), \'membership\':membership, \'path\':str(path),\\n            \'directory_identity\':[held_st.st_dev,held_st.st_ino],\\n            \'controller_pid\':os.getpid(), \'fields\':fields, \'events\':resource_events(fields[\'memory.events\'])}\\n\\ndef begin_resources():\\n    membership = Path(\'/proc/self/cgroup\').read_text().strip()\\n    require(\'\\\\n\' not in membership and membership.startswith(\'0::/user.slice/user-1000.slice/user@1000.service/app.slice/hepta-runtime-job-\'), \'not the exact owned user invocation\')\\n    path = Path(\'/sys/fs/cgroup\')/membership[3:].lstrip(\'/\')\\n    require(path.name.startswith(\'hepta-runtime-job-\') and path.name.endswith(\'.service\') and \'..\' not in path.parts, \'unexpected owned unit path\')\\n    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW)\\n    try:\\n        before = resource_snapshot(fd,membership)\\n        require(all(before[\'events\'][k] == 0 for k in [\'oom\',\'oom_kill\',\'oom_group_kill\']), \'owned invocation already recorded OOM before the control\')\\n        return fd,before\\n    except BaseException:\\n        os.close(fd)\\n        raise\\n\\ndef finish_resources(directory_fd, before, report):\\n    after = resource_snapshot(directory_fd,before[\'membership\'])\\n    report[\'owned_resources_after\'] = after\\n    report[\'owned_memory_peak\'] = int(after[\'fields\'][\'memory.peak\'])\\n    report[\'owned_memory_swap_peak\'] = int(after[\'fields\'][\'memory.swap.peak\'])\\n    require(after[\'directory_identity\'] == before[\'directory_identity\'], \'owned cgroup object replaced\')\\n    require(set(before[\'events\']) == set(after[\'events\']), \'owned memory event fields changed\')\\n    delta = {key:after[\'events\'][key]-value for key,value in before[\'events\'].items()}\\n    report[\'owned_memory_events_delta\'] = delta\\n    require(all(value >= 0 for value in delta.values()), \'owned memory event counters went backwards\')\\n    require(all(delta[key] == 0 for key in [\'oom\',\'oom_kill\',\'oom_group_kill\']), \'owned OOM event occurred; control is not qualified\')\\n    require(all(before[\'fields\'][key] == after[\'fields\'][key] for key in [\'memory.max\',\'memory.high\',\'memory.swap.max\',\'cpu.max\']), \'owned cgroup limits changed during control\')\\n    return {\'pass\':True, \'before\':before, \'after\':after, \'memory_events_delta\':delta,\\n            \'memory_peak\':int(after[\'fields\'][\'memory.peak\']), \'memory_swap_peak\':int(after[\'fields\'][\'memory.swap.peak\']),\\n            \'resource_settings_changed\':False, \'swap_max_observed_only\':after[\'fields\'][\'memory.swap.max\']}\\n\\ndef hash_held(path, maximum=512*1024*1024):\\n    fd = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW)\\n    try:\\n        before = os.fstat(fd)\\n        require(stat.S_ISREG(before.st_mode) and before.st_size <= maximum, \'unexpected held file type/size: \'+str(path))\\n        digest = hashlib.sha256()\\n        total = 0\\n        while True:\\n            raw = os.read(fd,65536)\\n            if not raw:\\n                break\\n            total += len(raw)\\n            require(total <= maximum, \'held file grew beyond bound: \'+str(path))\\n            digest.update(raw)\\n        require(total == before.st_size and identity(before) == identity(os.fstat(fd)) == identity(path.lstat()),\\n                \'held file changed: \'+str(path))\\n        return {\'path\':str(path),\'bytes\':total,\'sha256\':digest.hexdigest(),\'identity\':identity(before)}\\n    finally:\\n        os.close(fd)\\n\\ndef regular_tree(root, file_bound=2048, byte_bound=32*1024*1024):\\n    real_directory(root)\\n    rows = {}\\n    total = 0\\n    def walk_error(error):\\n        raise error\\n    for directory,dirs,files in os.walk(root,followlinks=False,onerror=walk_error):\\n        dirs.sort()\\n        for name in dirs:\\n            path=Path(directory)/name\\n            require(stat.S_ISDIR(path.lstat().st_mode),\'source directory alias rejected: \'+str(path))\\n        for name in sorted(files):\\n            path=Path(directory)/name\\n            relative=str(path.relative_to(root))\\n            require(relative not in rows and len(rows)<file_bound,\'source inventory bound or duplicate\')\\n            row=hash_held(path)\\n            total+=row[\'bytes\']\\n            require(total<=byte_bound,\'source inventory byte bound exceeded\')\\n            rows[relative]=row\\n    require(rows,\'empty source inventory: \'+str(root))\\n    return rows\\n\\ndef verify_resolved(rows):\\n    changes=[]\\n    for row in rows:\\n        try:\\n            path=Path(row[\'requested_path\'])\\n            resolved=path.resolve(strict=True)\\n            after=hash_held(resolved)\\n            if str(resolved)!=row[\'resolved_path\'] or after!={k:row[k] for k in [\'path\',\'bytes\',\'sha256\',\'identity\']}:\\n                changes.append(str(path))\\n        except Exception as error:\\n            changes.append({\'path\':row[\'requested_path\'],\'error\':repr(error)})\\n    return changes\\n\\nimport zipfile\\n\\nROOT = Path(\\"/home/alex/work/pocket4-nofile-owner-recovery03-android-build-01-20261105\\")\\nHERE = ROOT / \\"control-source\\"\\nOUT = ROOT / \\"coordinator01\\"\\nR3_SHA = \\"6f07583856f660eba100589f43114ff6b423659256363a9cf3883a334d6b4c81\\"\\nHOST_RESULT = Path(\\"/home/alex/work/pocket4-nofile-owner-recovery03-host-run-01-20261105/run01/result.json\\")\\nHOST_RESULT_SHA = \\"b0a03b1b95e3292131105dcb22fd59f4a767e63017197e29f4482036976a4ac2\\"\\nSOURCE_PINS_SHA = \\"21a644c1fd29fcaa0ff4368a4c39926168db8adff5880290f86af9fe18baf98b\\"\\n\\ndef input_rows(source, expected):\\n    real_directory(source)\\n    actual = set()\\n    for directory, dirs, files in os.walk(source, followlinks=False):\\n        dirs.sort()\\n        for name in list(dirs):\\n            child = Path(directory) / name\\n            require(stat.S_ISDIR(child.lstat().st_mode), \\"source directory alias: \\" + str(child))\\n            if child == source / \\"build-attempt-1\\":\\n                dirs.remove(name)\\n        for name in files:\\n            actual.add(str((Path(directory) / name).relative_to(source)))\\n    require(actual == set(expected), \\"source member set changed: \\" + str(source))\\n    rows = {}\\n    for name, wanted in expected.items():\\n        row = hash_held(source / name)\\n        require({key: row[key] for key in (\\"bytes\\", \\"sha256\\")} == wanted,\\n                \\"source bytes changed: \\" + name)\\n        rows[name] = row\\n    return rows\\n\\ndef package_binding(source, report):\\n    require(report[\\"state\\"] == \\"BU