\\"bytes\\": 1875,\\n      \\"sha256\\": \\"0878b6fe3d0059432b1bf7fc8041838ea9b36c3d1d0cfd9384b05d64bf52719f\\"\\n    },\\n    \\"preimage/berberis/kernel_api/proc_maps_raw_metadata_owner.h\\": {\\n      \\"bytes\\": 150,\\n      \\"sha256\\": \\"790cb30a463ae05385add83bbbc73c0b6a083cc18471e2894d53a87b4d9f113b\\"\\n    },\\n    \\"owner_probe.cpp\\": {\\n      \\"bytes\\": 3212,\\n      \\"sha256\\": \\"0d94208f4ad0f68be345f5a924d4e35e88ec3a8c6d761b4d7bff55e4c02569d1\\"\\n    }\\n  },\\n  \\"arm\\": \\"preimage\\",\\n  \\"native_controls\\": \\"unchanged recovery03 26-case harness; output transport only\\",\\n  \\"harness_sha256\\": \\"62c53acf7a58054a3ff4ea83e051a5630405955fe79cc59dcccc99b37e4264ef\\",\\n  \\"original_source_binding\\": \\"host recovery03 manifest baa504625fc51619824ef3023738b8b589008b9ef024fffdf6707ff726628aa3\\",\\n  \\"actual_host_result_sha256\\": \\"b0a03b1b95e3292131105dcb22fd59f4a767e63017197e29f4482036976a4ac2\\",\\n  \\"actual_android_compiled\\": false,\\n  \\"actual_android_executed\\": false,\\n  \\"production_ready\\": false\\n}\\n", "preimage/actual/berberis/kernel_api/proc_maps_factory_protocol.h": "// SPDX-License-Identifier: Apache-2.0\\n#ifndef BERBERIS_KERNEL_API_PROC_MAPS_FACTORY_PROTOCOL_H_\\n#define BERBERIS_KERNEL_API_PROC_MAPS_FACTORY_PROTOCOL_H_\\n// New V2 protocol. It records kernel inode origin, not application integrity.\\n// Statfs words explicitly retain the Linux LP64 raw ABI including ST_VALID.\\n// Every wire integer is little endian; no native C struct goes on the wire.\\n#include <stddef.h>\\n#include <stdint.h>\\n#include <sys/stat.h>\\n#include <sys/statfs.h>\\n#include <sys/types.h>\\n#include \\"proc_maps_kernel_statfs.h\\"\\n#if defined(__GNUC__)\\n#pragma GCC visibility push(hidden)\\n#endif\\nnamespace berberis::proc_maps_provenance {\\ninline constexpr char kTagName[] = \\"user.droidloom.proc_maps.v2\\";\\n// Immutable factory protocol shape, usable only as a negative exclusion. A\\n// matching display string never authenticates an inode; every positive path\\n// must still validate its root-owned sealed inode and complete origin tag.\\ninline constexpr char kSnapshotKernelPath[] = \\"/memfd:droidloom-proc-maps-v2 (deleted)\\";\\ninline constexpr char kTagMagic[8] = {\'D\', \'P\', \'4\', \'M\', \'A\', \'P\', \'S\', \'2\'};\\ninline constexpr char kRequestMagic[8] = {\'D\', \'P\', \'4\', \'R\', \'E\', \'Q\', \'0\', \'2\'};\\ninline constexpr char kReplyMagic[8] = {\'D\', \'P\', \'4\', \'R\', \'E\', \'P\', \'0\', \'2\'};\\ninline constexpr uint32_t kVersion = 2;\\ninline constexpr uint32_t kLinuxLp64RawStatfs = 1;\\ninline constexpr char kSocketName[] = \\"droidloom.proc_maps.v2\\";\\ninline constexpr char kSnapshotName[] = \\"droidloom-proc-maps-v2\\";\\ninline constexpr uint32_t kCreateSnapshot = 1;\\ninline constexpr size_t kRequestBytes = 64;\\ninline constexpr size_t kReplyBytes = 32;\\ninline constexpr size_t kMaxPathBytes = 4096;\\ninline constexpr uint64_t kMaxSnapshotBytes = 8u * 1024u * 1024u;\\ninline constexpr uint32_t kRequiredSeals = 15;  // SEAL|SHRINK|GROW|WRITE\\ninline constexpr uint64_t kTrustedUserNamespaceDevice = 5;\\ninline constexpr uint64_t kTrustedUserNamespaceInode = 4026531837ULL;\\n\\n// Request: magic[0:8], version u32@8, operation u32@12,\\n// payload_size u64@16, calling_tid u32@24, source_F_GETFL u32@28,\\n// original_F_GETFD u32@32, raw_statfs_encoding u32@36=1,\\n// ABI_bits u32@40=64, zero bytes[44:64]. Exactly two SCM_RIGHTS:\\n// (1) actual open maps in the authenticated peer\'s procfs view, (2) sealed input\\n// snapshot. The factory opens/verifies the actual peer\'s maps independently;\\n// path/metadata claims never come from this request. One request per connection.\\n// Reply: magic[0:8], version u32@8, positive errno u32@12 (zero on success),\\n// zero bytes[16:32]. Success has exactly one SCM_RIGHTS; failure has none.\\n// Both directions use SOCK_SEQPACKET; MSG_TRUNC/MSG_CTRUNC are errors.\\n\\n// Tag header: magic[0:8], version u32@8, total_length u32@12,\\n// path_length u32@16, raw_statfs_encoding u32@20=1. Then kWordCount u64 values, followed\\n// immediately by path_length bytes of the kernel origin readlink target.\\n// The target is nonempty, has no NUL, and is not terminated on the wire.\\n// statfs fsid words preserve the native 32-bit bit pattern, zero-extended.\\nenum TagWord : size_t {\\n  kFactoryUsernsDevice,\\n  kFactoryUsernsInode,\\n  kBackingDevice,\\n  kBackingInode,\\n  kBackingSize,\\n  kOriginTgid,\\n  kOriginStartTicks,\\n  kStatDevice,\\n  kStatInode,\\n  kStatMode,\\n  kStatNlink,\\n  kStatUid,\\n  kStatGid,\\n  kStatRdev,\\n  kStatSize,\\n  kStatBlockSize,\\n  kStatBlocks,\\n  kStatAtimeSeconds,\\n  kStatAtimeNanoseconds,\\n  kStatMtimeSeconds,\\n  kStatMtimeNanoseconds,\\n  kStatCtimeSeconds,\\n  kStatCtimeNanoseconds,\\n  kFsType,\\n  kFsBlockSize,\\n  kFsBlocks,\\n  kFsBlocksFree,\\n  kFsBlocksAvailable,\\n  kFsFiles,\\n  kFsFilesFree,\\n  kFsId0,\\n  kFsId1,\\n  kFsNameLength,\\n  kFsFragmentSize,\\n  kFsFlags,\\n  kFsSpare0,\\n  kFsSpare1,\\n  kFsSpare2,\\n  kFsSpare3,\\n  kWordCount\\n};\\ninline constexpr size_t kTagHeaderBytes = 24 + 8 * kWordCount;\\ninline constexpr size_t kMaxTagBytes = kTagHeaderBytes + kMaxPathBytes;\\n\\nstruct Origin {\\n  uint64_t words[kWordCount]{};\\n  char path[kMaxPathBytes]{};\\n  size_t path_size = 0;\\n};\\n\\nenum class Lookup { kOrdinary, kVirtual, kError };\\n\\n\\nuint32_t GetU32(const unsigned char* bytes);\\nuint64_t GetU64(const unsigned char* bytes);\\nvoid PutU32(unsigned char* bytes, uint32_t value);\\nvoid PutU64(unsigned char* bytes, uint64_t value);\\nbool DecodeOrigin(const unsigned char* bytes, size_t size, Origin* origin);\\nbool DecodeStat(const Origin& origin, struct stat* result);\\nbool DecodeKernelStatfs(const Origin& origin, KernelStatfs* result);\\nbool DecodeStatfs(const Origin& origin, struct statfs* result);\\nsize_t EncodeOrigin(const Origin& origin, unsigned char* output, size_t capacity);\\nstruct CreateRequest {\\n  uint64_t payload_size{};\\n  uint32_t caller_tid{};\\n  uint32_t source_flags{};\\n  uint32_t original_fd_flags{};\\n};\\nbool DecodeCreateRequest(const unsigned char* bytes, size_t size, CreateRequest* request);\\nbool EncodeCreateRequest(const CreateRequest& request, unsigned char output[kRequestBytes]);\\nvoid EncodeReply(uint32_t error, unsigned char output[kReplyBytes]);\\n\\n}  // namespace berberis::proc_maps_provenance\\n#if defined(__GNUC__)\\n#pragma GCC visibility pop\\n#endif\\n#endif\\n", "preimage/actual/berberis/kernel_api/proc_maps_fd_owner.h": "/* Copyright 2026. SPDX-License-Identifier: Apache-2.0 */\\n#ifndef BERBERIS_KERNEL_API_PROC_MAPS_FD_OWNER_H_\\n#define BERBERIS_KERNEL_API_PROC_MAPS_FD_OWNER_H_\\n\\n#if defined(__GNUC__)\\n#pragma GCC visibility push(hidden)\\n#endif\\n\\nnamespace berberis::proc_maps_provenance::fd_owner {\\n\\n// Run one metadata operation against the caller\'s real descriptor. The\\n// operation receives a kernel pin in an owner\'s independent fd table.\\n// No descriptor is installed in, or closed from, the caller\'s table. The\\n// callback and context must remain valid until this synchronous call returns.\\n//\\n// Until explicit startup opts into reuse, a short-lived owner avoids a queue\\n// or thread identity inherited by raw guest fork/clone. Reuse requires the\\n// lifecycle APIs below. Neither path moves pathname resolution into that\\n// thread: cwd, dirfd and /proc/thread-self need their own protocol. Required\\n// kernel/policy APIs must be qualified with the owned capability probe before\\n// enabling the provenance candidate on Android.\\nusing Operation = int (*)(int owned_fd, void* context);\\nint WithPinnedFd(int fd, Operation operation, void* context);\\n\\n// Opt in before entering guest code, while normal startup resources are still\\n// available. Once enabled, WithPinnedFd uses one already-created owner and a\\n// fixed single-request slot, with no pthread creation or queue allocation per\\n// metadata query. A guarded stack mapping survives Stop and private-memory\\n// fork so a child/restart does not need a new stack mmap. libc thread/TLS\\n// allocation and task-count limits still require separate qualification.\\n// This does not remove pidfd_open/getfd\'s RLIMIT_NOFILE needs.\\n// Pathname operations deliberately retain their per-request owner protocol.\\nint StartReusableMetadataOwner();\\n\\n// Close admission first, finish the last accepted request, then stop and join\\n// the owned thread. Requests arriving after admission closes return ESHUTDOWN;\\n// they never restart the owner. Only an explicit Start opens admission again.\\n// Invoke before the zygote\'s wait-for-no-host-threads/fork boundary.\\nint StopReusableMetadataOwner();\\n\\n// Only for a child with a PRIVATE copy of the parent\'s address space. Discard\\n// the copied queue/thread state without locking it, joining the vanished owner,\\n// or dereferencing a parent\'s outstanding request. This is also installed as a\\n// libc pthread_atfork child hook; raw guest clone(!CLONE_VM) must call it\\n// explicitly, then Start before resuming guest execution. A CLONE_VM child\\n// with a new TGID must never call this function: it shares the parent\'s state.\\nvoid ResetReusableMetadataOwnerAfterPrivateFork();\\n\\n// Operations run under the caller\'s synchronous request lifetime. They must\\n// not throw or recursively submit to this owner. A different TGID sharing this\\n// address space is rejected with EOPNOTSUPP without changing the owner\'s state.\\n\\n// The operation receives a PIDFD_THREAD for the calling thread, in the\\n// independent table. It may acquire caller dirfds with pidfd_getfd; passing a\\n// caller descriptor number directly to an owner syscall is never correct.\\nint WithPrivateTable(Operation operation, void* context);\\n\\n// Prepare returns a descriptor owned solely by the independent table. Publish\\n// runs on the caller, while that descriptor and its owner remain alive. The\\n// caller performs one final open of private_path to publish a NEW descriptor;\\n// it must not reserve/overwrite a slot or inspect/close the public result.\\n// This protocol is for a regular snapshot that can be reopened without side\\n// effects, not arbitrary devices, sockets, pipes, or an OFD transfer.\\nusing Publication = int (*)(const char* private_path, void* context);\\nint WithPreparedFile(Operation prepare, Publication publish, void* context);\\n\\n}  // namespace berberis::proc_maps_provenance::fd_owner\\n#if defined(__GNUC__)\\n#pragma GCC visibility pop\\n#endif\\n#endif\\n", "preimage/actual/berberis/kernel_api/proc_maps_kernel_statfs.h": "// SPDX-License-Identifier: Apache-2.0\\n#ifndef BERBERIS_KERNEL_API_PROC_MAPS_KERNEL_STATFS_H_\\n#define BERBERIS_KERNEL_API_PROC_MAPS_KERNEL_STATFS_H_\\n\\n#include <stddef.h>\\n#include <stdint.h>\\n#include <string.h>\\n#include <sys/statfs.h>\\n#include <type_traits>\\n\\nnamespace berberis::proc_maps_provenance {\\n\\n// Linux asm-generic/statfs.h LP64 raw-syscall representation, shared by\\n// x86_64 and arm64. These members retain kernel bits, not libc semantics.\\n// Never construct it by adding flags to an already-normalized libc result.\\nstruct KernelStatfs {\\n  uint64_t f_type{}, f_bsize{}, f_blocks{}, f_bfree{}, f_bavail{};\\n  uint64_t f_files{}, f_ffree{};\\n  uint32_t f_fsid[2]{};\\n  uint64_t f_namelen{}, f_frsize{}, f_flags{}, f_spare[4]{};\\n};\\nstatic_assert(sizeof(long) == 8);\\nstatic_assert(std::is_standard_layout_v<KernelStatfs>);\\nstatic_assert(std::is_trivially_copyable_v<KernelStatfs>);\\nstatic_assert(sizeof(KernelStatfs) == 120 && alignof(KernelStatfs) == 8);\\nstatic_assert(sizeof(struct statfs) == sizeof(KernelStatfs));\\n#define BERBERIS_CHECK_KERNEL_STATFS_FIELD(field, offset, bytes) \\\\\\n  static_assert(offsetof(KernelStatfs, field) == offset); \\\\\\n  static_assert(sizeof(KernelStatfs::field) == bytes); \\\\\\n  static_assert(offsetof(struct statfs, field) == offset); \\\\\\n  static_assert(sizeof(((struct statfs*)nullptr)->field) == bytes)\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_type, 0, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_bsize, 8, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_blocks, 16, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_bfree, 24, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_bavail, 32, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_files, 40, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_ffree, 48, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_fsid, 56, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_namelen, 64, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_frsize, 72, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_flags, 80, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_spare, 88, 32);\\n#undef BERBERIS_CHECK_KERNEL_STATFS_FIELD\\n\\n// Caller-side conversion only. The fixed worker writes KernelStatfs directly.\\n// The host libc ABI has the asserted layout above, but Bionic\'s successful\\n// fstatfs wrapper clears ST_VALID. Preserve every other bit and raw snapshot.\\ninline void KernelStatfsToLibc(const KernelStatfs& kernel, struct statfs* result) {\\n  memcpy(result, &kernel, sizeof(kernel));\\n#if defined(__BIONIC__)\\n  result->f_flags &= ~0x0020;\\n#endif\\n}\\n}  // namespace berberis::proc_maps_provenance\\n#endif\\n", "preimage/actual/berberis/kernel_api/proc_maps_path.h": "/* Copyright 2026. SPDX-License-Identifier: Apache-2.0 */\\n#ifndef BERBERIS_KERNEL_API_PROC_MAPS_PATH_H_\\n#define BERBERIS_KERNEL_API_PROC_MAPS_PATH_H_\\n\\n#include <stddef.h>\\n#include <sys/stat.h>\\n\\n#if defined(__GNUC__)\\n#pragma GCC visibility push(hidden)\\n#endif\\n\\nnamespace berberis::proc_maps_provenance::path {\\n\\nconstexpr size_t kPathBytes = 4096;\\n\\n// A kernel-mediated copy; never dereference the guest pathname in host code.\\nint CopyFromCaller(const char* source, char (&destination)[kPathBytes]);\\n\\nstruct CallerView {\\n  char thread_label[96]{};\\n  struct stat thread_self{};\\n};\\n\\n// Captu